package dev.workshopvideo;
import android.app.Activity;import android.graphics.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;
/** Build an explicit image-layer scene from the user's own saved images; no video-to-depth claim. */
final class SceneComposer {
 private final Activity activity;private final VideoApp app;SceneComposer(Activity activity,VideoApp app){this.activity=activity;this.app=app;}
 void show(String initialId){AppSheet sheet=new AppSheet(activity,"制作分层场景","按选择顺序从背景到前景叠加；透明 PNG 适合作为前景。最多 8 层。",null);ArrayList<JSONObject> entries=new ArrayList<>();ArrayList<JSONObject> selected=new ArrayList<>();for(JSONObject item:app.jobs())if(item.optString("state").equals("saved")&&item.optString("kind").equals("image")&&item.optBoolean("compatible",true))entries.add(item);
  if(entries.isEmpty()){TextView text=new TextView(activity);text.setText("请先从发现下载图片，再选择背景图与前景图。");text.setTextColor(Ui.TEXT);sheet.field(text);}for(JSONObject item:entries){CheckBox choose=new CheckBox(activity);choose.setText(item.optString("title"));choose.setTextColor(Ui.TEXT);choose.setOnCheckedChangeListener((button,on)->{if(on){if(selected.size()>=8){choose.setChecked(false);Toast.makeText(activity,"最多选择 8 层",0).show();return;}selected.add(item);}else selected.remove(item);});if(item.optString("id").equals(initialId))choose.setChecked(true);sheet.field(choose);}
  sheet.footerButton("取消",false,()->sheet.dialog.dismiss());sheet.footerButton("创建场景",true,()->{if(selected.size()<2){Toast.makeText(activity,"请选择至少两张图片",0).show();return;}sheet.dialog.dismiss();app.work.submit(()->{try{JSONObject scene=create(selected);activity.runOnUiThread(()->{Toast.makeText(activity,"分层场景已保存到图片与场景",1).show();activity.startActivity(new android.content.Intent(activity,WallpaperSetupActivity.class).putExtra("id",scene.optString("id")));});}catch(Exception e){activity.runOnUiThread(()->Toast.makeText(activity,VideoApp.error(e),1).show());}});});sheet.show();
 }
 private JSONObject create(List<JSONObject> images)throws Exception {
  String id=UUID.randomUUID().toString().replace("-","");File target=app.video(id);target.getParentFile().mkdirs();boolean saved=false;
  try{JSONObject root=new JSONObject().put("format","WallpaperMobileScene/1").put("width",1080).put("height",2400);JSONArray layers=new JSONArray();JSONObject options=EffectOptions.normalize(null);options.put("gyro",true);options.put("touch",true);root.put("effects",options);
   try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(target))){int i=0;for(JSONObject item:images){String name="layers/"+i+".png";zip.putNextEntry(new ZipEntry(name));Bitmap image=WallpaperContent.image(app.video(item.optString("id")),2048);float ratio=Math.max(1080f/image.getWidth(),2400f/image.getHeight());float layerWidth=image.getWidth()*ratio,layerHeight=image.getHeight()*ratio;try{if(!image.compress(Bitmap.CompressFormat.PNG,100,zip))throw new IOException("无法保存场景图片");}finally{image.recycle();}zip.closeEntry();layers.put(new JSONObject().put("file",name).put("width",layerWidth).put("height",layerHeight).put("x",(1080-layerWidth)/2).put("y",(2400-layerHeight)/2).put("depth",i*.35));i++;}root.put("layers",layers);zip.putNextEntry(new ZipEntry("wallpaper-mobile.json"));zip.write(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));zip.closeEntry();}
   try(WallpaperContent.Scene test=WallpaperContent.scene(target)){}JSONObject record=new JSONObject().put("id",id).put("itemId","local:"+id).put("title","分层场景 · "+images.size()+" 层").put("kind","scene").put("state","saved").put("storage","private").put("local",true).put("compatible",true).put("created",System.currentTimeMillis()).put("size",target.length()).put("effects",options).put("uri",app.videoUri(id));app.save(record);saved=true;return record;
  }finally{if(!saved)target.delete();}
 }
}
